{
  return ocioOCIOTransform(
    ocio_reach_m_table_0
    , ocio_reach_m_table_0Sampler
    , ocio_gamut_cusp_table_0
    , ocio_gamut_cusp_table_0Sampler
  ).OCIOTransform(inPixel);
}


// ── Kernel wrapper ───────────────────────────────────────────────────────
kernel void ocioInverseColorTransform(
        texture2d<float, access::read>  inputTexture  [[texture(0)]],
        texture2d<float, access::write> outputTexture [[texture(1)]],
                texture1d<float, access::sample> ocio_reach_m_table_0 [[texture(2)]],
                texture1d<float, access::sample> ocio_gamut_cusp_table_0 [[texture(3)]],
        uint2 gid [[thread_position_in_grid]]
) {
    if (gid.x >= outputTexture.get_width() || gid.y >= outputTexture.get_height()) { return; }

    constexpr sampler linearSampler(coord::normalized, address::clamp_to_edge, filter::linear);
    constexpr sampler nearestSampler(coord::normalized, address::clamp_to_edge, filter::nearest);

    float4 color = inputTexture.read(gid);

    // sRGB-encoded display → scene-linear AP0
    color = OCIOTransform(
            ocio_reach_m_table_0,
                    nearestSampler,
                    ocio_gamut_cusp_table_0,
                    nearestSampler,
                    color
    );

    outputTexture.write(color, gid);
}
